'use client';
const require_badge = require("./badge.cjs");
const require_badge_position = require("./badge-position.cjs");
//#region src/components/badge/index.ts
/**
* `Badge` is a non-interactive component for displaying status with or without numbers.
*
* @example without children
* <Badge count={5} maxCount={10} />
*/
const Badge = Object.assign(require_badge.Badge, { Position: require_badge_position.BadgePosition });
Badge.Position.displayName = "Badge.Position";
//#endregion
exports.Badge = Badge;
exports.BadgePosition = require_badge_position.BadgePosition;
